/*
SQL ID: com.winter.winter_back.domain.address.dao.AddressDao.regAddress
SQL 명: 주소 등록
*/
INSERT INTO tb_user_address ( user_id
                            , alias
                            , base_address
                            , detail_address
                            , latitude
                            , longitude
                            , is_default
                            , delivery_instructions
                            , created_at
                            , updated_at)
VALUES ( #{userId}
       , #{alias}
       , #{baseAddress}
       , #{detailAddress}
       , #{latitude}
       , #{longitude}
       , #{isDefault}
       , #{deliveryInstructions}
       , CURRENT_TIMESTAMP()
       , CURRENT_TIMESTAMP())

mapper.update:
/*
SQL ID: com.winter.winter_back.domain.address.dao.AddressDao.modAddress
SQL 명: 주소 수정
*/
UPDATE tb_user_address
SET alias                 = #{alias}
  , base_address          = #{baseAddress}
  , detail_address        = #{detailAddress}
  , latitude              = #{latitude}
  , longitude             = #{longitude}
  , delivery_instructions = #{deliveryInstructions}
  , updated_at            = CURRENT_TIMESTAMP()
WHERE idx = #{idx}
  AND user_id = #{userId}

